from fx import *
import math
PG.configure('/festivals/panchanga/',[('','The Pañcāṅga','How the Hindu Calendar Works')],'navy','Pañcāṅga','Lord','Pañcāṅga')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/panchanga/'
i=0
def phases(n=15,x0=30,dx=35,y=70,r=13,fill_to=None,hi=None):
    o=''
    for k in range(n):
        f='#fff8d0' if (fill_to is None or k<fill_to) else '#cfd8e6'
        o+=f'<circle cx="{x0+k*dx}" cy="{y}" r="{r}" fill="{f}" stroke="#111" stroke-width="1.5"/>'
    if hi is not None: o+=f'<circle cx="{x0+hi*dx}" cy="{y}" r="{r+6}" fill="none" stroke="#c0392b" stroke-width="3"/>'
    return o
def wheel(n,r=60,lab_=None,hi=None):
    o=f'<circle r="{r}" fill="#fff8e7"/><circle r="{r*0.62:.0f}" fill="#e3eaf3"/>'
    for k in range(n):
        a=(k*360/n-90)*math.pi/180; o+=f'<path d="M{r*0.62*math.cos(a):.1f} {r*0.62*math.sin(a):.1f} L{r*math.cos(a):.1f} {r*math.sin(a):.1f}" stroke-width="1"/>'
    if hi is not None:
        a=((hi+.5)*360/n-90)*math.pi/180; o+=f'<circle cx="{r*0.81*math.cos(a):.1f}" cy="{r*0.81*math.sin(a):.1f}" r="7" fill="#ffd60a"/>'
    return o
def almanac(): return '<rect x="-34" y="-46" width="68" height="50" rx="3" fill="#fff8e7"/><path d="M0 -46 v50" stroke-width="1.5"/>'+''.join(f'<path d="M-28 {-38+k*8} h22 M6 {-38+k*8} h22" stroke="#888" stroke-width="1.5"/>' for k in range(5))
COV=covart('A palm-leaf almanac open beside a sun and a moon, with a wheel of twelve signs and a row of moon phases',f'<rect width="440" height="196" fill="#20243a"/>'+''.join(f'<circle cx="{(37*k)%440}" cy="{(23*k*k)%80+6}" r="1.3" fill="#fff8d0" stroke="none"/>' for k in range(1,16))+g(90,70,1,sun(22))+g(350,70,1,moon())+g(220,80,.9,wheel(12,hi=9))+'<rect y="150" width="440" height="46" fill="#3a4a6a"/>'+g(220,186,1.6,almanac())+phases(7,40,8,175,3).replace('cx="','cx="').replace('stroke-width="1.5"','stroke-width=".5"'))
pp=[foreword(i,['Every festival on this site is dated by the <b>pañcāṅga</b>, the Hindu almanac: “five limbs”, the five measures of each day: <b>tithi</b> (lunar day), <b>vāra</b> (weekday), <b>nakṣatra</b> (the moon’s mansion), <b>yoga</b> and <b>karaṇa</b>. Learn these and every puzzle about festival dates (why Dīpāvali moves, why Śivarātri is in Māgha in Karnataka and Phālguna in Delhi, why your friend keeps Janmāṣṭamī a day later) solves itself.','This article explains each limb with a picture, the months and seasons, the two ways of ending a month, the solar months and saṅkrāntis, the extra month, the eras and the sixty named years, how a festival’s day is chosen, how to read a page of a pañcāṅga, and closes with a month-by-month map of the festivals, so you can find any of them.'],[('z','Why can’t festivals just stay on the same date?'),('b','Because most follow the moon, Zappy, and the moon doesn’t keep our calendar. Let me show you how it works.')]),
 glance([('Pañcāṅga','“Five limbs”: tithi, vāra, nakṣatra, yoga, karaṇa'),('Tithi','Lunar day: each 12° the moon gains on the sun; 30 a month'),('Vāra','Weekday, sunrise to sunrise, named for seven planets'),('Nakṣatra','The moon’s place among 27 star-groups of 13°20′'),('Yoga, karaṇa','Sun + moon divided in 27; half a tithi (6°)'),('Months','12 lunar months, Caitra to Phālguna; six ṛtus'),('Calendars','Amānta (month ends at new moon: Karnataka) and pūrṇimānta (at full moon: the north); solar months by saṅkrānti'),('Correction','An extra month (adhika māsa) about every 32–33 months')],svg(560,140,'Five icons for the five limbs',f'<rect width="560" height="140" fill="#fffaf0"/>'+g(70,90,.9,moon())+g(180,90,.9,sun(16))+g(290,90,.5,wheel(27))+g(400,90,.9,'<circle r="18" fill="#e3eaf3"/><path d="M-18 0 h36" stroke-width="2"/>')+g(500,90,.9,'<circle r="18" fill="#fff8d0"/><path d="M0 -18 v36" stroke-width="2"/>')+''.join(lab(x,130,t) for x,t in [(70,'tithi'),(180,'vāra'),(290,'nakṣatra'),(400,'yoga'),(500,'karaṇa')]))),
 reading('tithi','TITHI','The lunar day',svg(560,160,'Thirty moon phases in two rows, bright and dark fortnights',f'<rect width="560" height="160" fill="#20243a"/>'+phases(15,40,34,45,11)+''.join(f'<circle cx="{40+k*34}" cy="115" r="11" fill="{"#fff8d0" if k<15-k else "#3a4a6a"}" stroke="#cfd8e6" stroke-width="1"/>' for k in range(15))+lab(500,25,'śukla: waxing').replace('#111','#fff8d0')+lab(500,145,'kṛṣṇa: waning').replace('#111','#fff8d0')),['<b>Definition.</b> A tithi is the time the moon takes to gain 12° on the sun (in the bright fortnight) or to close 12° (in the dark). There are thirty in a lunar month: fifteen in the bright half (<b>śukla pakṣa</b>), ending at full moon (<b>pūrṇimā</b>), and fifteen in the dark half (<b>kṛṣṇa pakṣa</b>), ending at new moon (<b>amāvāsyā</b>).','<b>Names.</b> Pratipadā (1st), dvitīyā, tṛtīyā, caturthī, pañcamī, ṣaṣṭhī, saptamī, aṣṭamī, navamī, daśamī, ekādaśī, dvādaśī, trayodaśī, caturdaśī, then pūrṇimā or amāvāsyā. You know many from festival names: Gaṇeśa Caturthī, Rāma Navamī, Kṛṣṇa Aṣṭamī.','<b>Uneven length.</b> Because the moon’s speed varies, a tithi lasts roughly 19 to 26 hours. Sometimes one begins and ends between two sunrises and is “lost” (<b>kṣaya</b>); sometimes one spans two sunrises (<b>adhika</b>).','<b>Why it matters.</b> Most festivals are fixed by tithi. That is why they wander against the Western calendar, and why almanacs occasionally disagree by a day.'],[('z','A day that isn’t 24 hours?'),('b','A tithi is moon-time, not clock-time, Zappy. That’s why festivals sometimes fall on two dates.')],'Moon-time, <b>not clock-time</b>.'),
 reading('vara','VĀRA','The weekday',svg(560,150,'Seven circles for the seven weekdays with sun, moon and planets',f'<rect width="560" height="150" fill="#fffaf0"/>'+''.join(f'<circle cx="{50+k*76}" cy="65" r="22" fill="{c}" stroke="#111" stroke-width="1.5"/>'+lab(50+k*76,115,t) for k,(c,t) in enumerate([('#ffd60a','Ravi'),('#fff8d0','Soma'),('#c0392b','Maṅgala'),('#2a9d6f','Budha'),('#e0a800','Guru'),('#f4f1ea','Śukra'),('#3a3a5a','Śani')]))),['<b>The same week.</b> The Indian week has the same seven planetary days as the European: Ravi (Sun: Sunday), Soma (Moon: Monday), Maṅgala (Mars: Tuesday), Budha (Mercury: Wednesday), Guru or Bṛhaspati (Jupiter: Thursday), Śukra (Venus: Friday), Śani (Saturn: Saturday).','<b>Sunrise to sunrise.</b> The Hindu day runs from sunrise to sunrise, not midnight to midnight. So the “day” on which a tithi falls is reckoned from sunrise.','<b>Devotional days.</b> Each weekday has its deity in popular practice: Monday Śiva, Tuesday Devī and Hanumān, Thursday the guru and Rāghavendra, Friday Lakṣmī, Saturday Veṅkaṭeśvara and Śani. Some festivals are weekday-bound: '+L('/festivals/varamahalakshmi/','Varamahālakṣmī')+' on a Friday, '+L('/festivals/kartika/somavara-lakshadipotsava/','Kārtika Mondays')+'.','<b>Special combinations.</b> A Pradoṣa on Monday or Saturday, or an amāvāsyā on Monday (Somavatī), is counted especially holy.'],[('z','Why is Tuesday Maṅgala?'),('b','Each weekday is named after a planet, Zappy, like Monday after the moon. Same idea, older names.')],'Seven days, <b>seven planets</b>.'),
 reading('nakshatra','NAKṢATRA','The moon’s twenty-seven mansions',svg(560,170,'A wheel divided into 27 segments with the moon in one of them',f'<rect width="560" height="170" fill="#20243a"/>'+g(170,85,1.2,wheel(27,hi=3))+''.join(lab(420,30+k*22,t).replace('#111','#fff8d0') for k,t in enumerate(['1 Aśvinī','3 Kṛttikā','4 Rohiṇī','8 Puṣya','22 Śravaṇa','27 Revatī']))),['<b>Definition.</b> The moon goes round the sky in about 27⅓ days. The circle of the sky is divided into <b>27 nakṣatras</b> of 13°20′ each, star-groups the moon “stays in” for about a day: Aśvinī, Bharaṇī, Kṛttikā, Rohiṇī, Mṛgaśiras, Ārdrā, Punarvasu, Puṣya, Āśleṣā, Maghā… Śravaṇa… Revatī.','<b>Birth stars.</b> Your <i>janma nakṣatra</i> is where the moon was at your birth; in Karnataka families it decides names, and many celebrate the star-birthday rather than the date.','<b>Festivals by star.</b> Some festivals follow a nakṣatra instead of, or as well as, a tithi: '+L('/festivals/kartika/karthigai-deepam/','Kārttikai Dīpam')+' with Kṛttikā, Ōṇam with Śravaṇa, Rāma born under Punarvasu, Kṛṣṇa under Rohiṇī.','<b>Month names.</b> The months themselves are named for nakṣatras (next page but one).'],[('z','Twenty-seven, not twelve?'),('b','Twelve signs for the sun, Zappy, twenty-seven mansions for the moon. The moon needs a room for each night.')],'A room <b>for each night</b>.'),
 reading('yoga','YOGA AND KARAṆA','The last two limbs',svg(560,150,'Sun and moon positions added for yoga, and a half-moon slice for karaṇa',f'<rect width="560" height="150" fill="#fffaf0"/>'+g(120,75,.9,sun(18))+txt(170,82,'+',30)+g(220,75,.9,moon())+txt(270,82,'→ 27 yogas',16)+g(440,75,1,'<circle r="30" fill="#fff8d0"/><path d="M0 -30 v60" stroke-width="2"/>')+lab(440,130,'karaṇa = ½ tithi')),['<b>Yoga.</b> Add the longitudes of the sun and moon, and divide the total into 27 parts of 13°20′: the 27 yogas, from <b>Viṣkambha</b>, Prīti, Āyuṣmān… through Siddhi and Vyatīpāta to Vaidhṛti. (Not to be confused with yoga the discipline.)','<b>Karaṇa.</b> Half a tithi, 6° of separation between moon and sun: sixty karaṇas in a month. There are eleven kinds: seven movable ones that repeat eight times, and four fixed ones at the month’s end.','<b>Bhadrā.</b> One karaṇa, <b>Viṣṭi</b> or <b>Bhadrā</b>, is widely avoided for beginnings: Holikā Dahana and Rakṣā Bandhan, for example, are timed to avoid it.','<b>Who uses them.</b> Mostly priests and astrologers choosing a <b>muhūrta</b>, an auspicious time. For festivals the tithi matters most.'],[('z','Do people still use yoga and karaṇa?'),('b','Mostly priests and astrologers, to pick good times, Zappy. For festivals, tithi matters most.')],'Fine tuning <b>for good times</b>.'),
 reading('months','THE TWELVE MONTHS AND SIX SEASONS','From Caitra to Phālguna',svg(560,170,'A ring of twelve months grouped into six seasons with icons',f'<rect width="560" height="170" fill="#fffaf0"/>'+g(170,85,1.2,wheel(12,hi=0))+''.join(lab(420,25+k*24,t) for k,t in enumerate(['vasanta: Caitra, Vaiśākha','grīṣma: Jyeṣṭha, Āṣāḍha','varṣā: Śrāvaṇa, Bhādrapada','śarad: Āśvayuja, Kārtika','hemanta: Mārgaśīrṣa, Pauṣa','śiśira: Māgha, Phālguna']))),['<b>The months.</b> Caitra, Vaiśākha, Jyeṣṭha, Āṣāḍha, Śrāvaṇa, Bhādrapada, Āśvayuja (Āśvina), Kārtika, Mārgaśīrṣa, Pauṣa (Puṣya), Māgha, Phālguna. Karnataka, Andhra, Telaṅgāṇa and Maharashtra begin the year with Caitra at '+L('/festivals/ugadi/','Ugādi')+'.','<b>Named by the stars.</b> Each month takes its name from the nakṣatra near which its full moon falls: Caitra from Citrā, Vaiśākha from Viśākhā, Kārtika from Kṛttikā, Māgha from Maghā, and so on.','<b>Six seasons.</b> Two months make each <b>ṛtu</b>: vasanta (spring), grīṣma (summer), varṣā (rains), śarad (autumn), hemanta (pre-winter), śiśira (winter).','<b>Two halves.</b> The year also has two <b>ayanas</b>: uttarāyaṇa, when the sun moves north, and dakṣiṇāyana, when it moves south (read our '+L('/festivals/makara-sankranti/','Makara Saṅkrānti')+' article for the astronomy).'],[('z','Six seasons?'),('b','Six ṛtus of two months each, Zappy. India’s weather really does have six moods.')],'Twelve months, <b>six seasons</b>.'),
 reading('amanta','AMĀNTA AND PŪRṆIMĀNTA','When does a month end?',svg(560,170,'Two timelines: one month ending at new moon, the other at full moon, with the same night labelled differently',f'<rect width="560" height="170" fill="#fffaf0"/>'+'<path d="M40 60 h480 M40 120 h480" stroke-width="2"/>'+''.join(f'<circle cx="{x}" cy="{y}" r="10" fill="{c}" stroke="#111" stroke-width="1.5"/>' for x,y,c in [(160,60,'#20243a'),(400,60,'#20243a'),(280,120,'#fff8d0'),(520,120,'#fff8d0')])+lab(100,45,'Māgha (amānta)')+lab(280,45,'Phālguna')+lab(160,105,'Māgha (pūrṇimānta)')+lab(400,105,'Phālguna')+'<path d="M340 30 v110" stroke="#c0392b" stroke-width="2" stroke-dasharray="4 3"/>'+lab(340,160,'the same dark-fortnight night')),['<b>Two systems.</b> In the <b>amānta</b> system, used in Karnataka, Maharashtra, Gujarat, Goa, Andhra and Telaṅgāṇa, the month ends at the new moon. In the <b>pūrṇimānta</b> system, used in Nepal and most of India north of the Vindhyas, it ends at the full moon.','<b>Same bright half.</b> The bright fortnight has the same month name in both.','<b>Different dark half.</b> In the dark fortnight the north has already moved on to the next month. So '+L('/festivals/maha-shivaratri/','Mahāśivarātri')+' is Māgha Kṛṣṇa Caturdaśī in Karnataka and Phālguna Kṛṣṇa Caturdaśī in Uttar Pradesh, yet it is the same night everywhere. Janmāṣṭamī (Śrāvaṇa/Bhādrapada) and Dīpāvali’s new moon (Āśvayuja/Kārtika) work the same way.','<b>The rule of thumb.</b> When a festival list seems to disagree by a month, check whether the date is in the dark fortnight. Nine times out of ten, that is the reason.'],[('z','So the north and the south disagree?'),('b','Only on the name of the month, Zappy. The night is the same.')],'Same night, <b>two month names</b>.'),
 reading('solar','SOLAR MONTHS AND SAṄKRĀNTI','The sun’s calendar',svg(560,160,'The sun stepping from one zodiac sign to the next',f'<rect width="560" height="160" fill="#fde9c8"/>'+g(170,80,1.1,wheel(12,hi=9))+''.join(lab(420,30+k*24,t) for k,t in enumerate(['Makara: ~14–15 Jan','Meṣa: ~14 Apr, solar new year','Siṃha: Ōṇam’s month','Dhanus: Mārgaḻi']))),['<b>Rāśis.</b> The sun’s path is divided into twelve <b>rāśis</b>, signs of 30°: Meṣa (Aries), Vṛṣabha, Mithuna, Karkaṭa, Siṃha, Kanyā, Tulā, Vṛścika, Dhanus, Makara, Kumbha, Mīna.','<b>Saṅkrānti.</b> The sun’s entry into a sign is a <b>saṅkrānti</b>, and in the solar calendar the month takes that sign’s name. Solar festivals hardly move against the Western calendar: Makara Saṅkrānti around 14–15 January, Meṣa Saṅkrānti, the solar new year, around 14–15 April.','<b>Solar regions.</b> Tamil Nadu, Kerala, Bengal, Assam and Odisha keep solar months for their civil calendar; Tuḷunāḍu keeps a solar year too. They still use tithis for many festivals.','<b>Mixed rules.</b> Some festivals combine the two: '+L('/festivals/vaikuntha-ekadashi/','Vaikuṇṭha Ekādaśī')+' is the bright Ekādaśī that falls in solar Dhanus; Ōṇam is Śravaṇa nakṣatra in solar Siṃha.'],[('z','Why is Saṅkrānti always mid-January?'),('b','It follows the sun, not the moon, Zappy. Solar festivals hardly move.')],'The sun <b>keeps its dates</b>.'),
 reading('adhika','ADHIKA MĀSA','The extra month',svg(560,150,'Twelve month boxes with a thirteenth inserted',f'<rect width="560" height="150" fill="#fffaf0"/>'+''.join(f'<rect x="{20+k*40}" y="50" width="34" height="40" rx="4" fill="{"#ffd60a" if k==5 else "#e3eaf3"}" stroke="#111" stroke-width="1.5"/>' for k in range(13))+lab(225,115,'adhika: the month with no saṅkrānti, repeated')),['<b>The problem.</b> Twelve lunar months come to about 354 days, some 11 days short of the solar year. Left alone, festivals would drift through the seasons: Ugādi would arrive in winter.','<b>The fix.</b> About every 32–33 months an extra month is inserted. The rule: when a lunar month passes with no saṅkrānti (the sun not entering a new sign during it), that month is repeated. The first is the <b>adhika</b> (extra) month, the second the regular (<i>nija</i>) one.','<b>Names and customs.</b> The extra month is called adhika, <b>puruṣottama</b> (dedicated to Viṣṇu) or mala (“impure”) māsa. Weddings and new ventures are generally avoided in it, but devotion, charity and pilgrimage are encouraged.','<b>The rare opposite.</b> Very rarely a month contains two saṅkrāntis and one month is dropped (<b>kṣaya māsa</b>); an adhika month always comes in the same year to balance it.'],[('z','A thirteen-month year?'),('b','Yes, Zappy, every few years. It keeps Ugādi in spring and Dīpāvali in autumn.')],'A month added <b>to keep the seasons</b>.'),
 reading('eras','ERAS AND THE SIXTY YEARS','Counting the years',svg(560,150,'A sixty-division wheel and three era labels',f'<rect width="560" height="150" fill="#fffaf0"/>'+g(130,75,1.1,wheel(60))+''.join(lab(400,30+k*26,t) for k,t in enumerate(['Vikrama Saṃvat: from 57 BCE','Śaka: from 78 CE','Kali yuga: traditional','60 named years: Prabhava…Akṣaya']))),['<b>Vikrama Saṃvat.</b> Counted from 57 BCE; common in the north and west, beginning in Caitra (or Kārtika in Gujarat).','<b>Śaka.</b> Counted from 78 CE; common in the south, and the base of India’s national calendar. Karnataka’s almanacs give the Śālivāhana Śaka year.','<b>Kali yuga.</b> A traditional reckoning of over five thousand years from the start of the present age.','<b>Sixty names.</b> In the south each year also has a name from a cycle of sixty, from Prabhava through Akṣaya, changing at Ugādi. Completing the cycle at sixty is celebrated as <b>ṣaṣṭyabdapūrti</b>. Read our '+L('/festivals/ugadi/','Ugādi')+' article.'],[('z','Sixty names, then repeat?'),('b','Exactly, Zappy. A person who lives to sixty sees their birth-year name again.')],'Three eras, <b>sixty names</b>.'),
 reading('dating','HOW A FESTIVAL IS DATED','Which day counts?',svg(560,150,'A clock face with sunrise, midday, dusk and midnight marked for different festivals',f'<rect width="560" height="150" fill="#fffaf0"/>'+g(150,75,1,'<circle r="55" fill="#e3eaf3"/>'+''.join(f'<circle cx="{45*math.cos(a):.1f}" cy="{45*math.sin(a):.1f}" r="7" fill="{c}"/>' for a,c in [(-1.57,'#ffd60a'),(0,'#ff8c1a'),(1.57,'#20243a'),(3.14,'#fff8d0')]))+''.join(lab(400,30+k*24,t) for k,t in enumerate(['sunrise: most festivals','midday: Rāma Navamī, Gaṇeśa','dusk: Pradoṣa','midnight: Janmāṣṭamī, Śivarātri']))),['<b>Basic rule.</b> A festival is defined by a month, fortnight and tithi: Caitra Śukla Navamī for Rāma Navamī, Bhādrapada Śukla Caturthī for Gaṇeśa.','<b>The sunrise rule.</b> Because tithis do not line up with days, rules decide which day counts. Many festivals take the tithi prevailing at sunrise.','<b>Time-of-day rules.</b> Others look to a particular hour: '+L('/festivals/rama-navami/','Rāma Navamī')+' to midday, when Rāma was born; '+L('/festivals/krishna-janmashtami/','Janmāṣṭamī')+' to midnight, some traditions also requiring Rohiṇī; '+L('/festivals/maha-shivaratri/','Śivarātri')+' to the night; '+L('/festivals/pradosha/','Pradoṣa')+' to dusk.','<b>Why almanacs differ.</b> Different regions, traditions (Smārta, Vaiṣṇava, Mādhva) and calculation methods (old siddhānta tables or modern “dṛk” astronomy) can put a festival a day apart. Each guide on this site notes such differences.'],[('z','Why does my friend’s family keep Janmāṣṭamī a day later?'),('b','Different rules, Zappy: some follow the tithi, some the Rohiṇī star. Both are right for them.')],'The hour <b>decides the day</b>.'),
 reading('reading','READING A PAÑCĀṄGA','A sample day',svg(560,170,'An open almanac page with labelled rows',f'<rect width="560" height="170" fill="#fffaf0"/>'+'<rect x="120" y="10" width="320" height="150" rx="6" fill="#fff8e7" stroke="#111" stroke-width="2"/>'+''.join(lab(280,32+k*18,t) for k,t in enumerate(['saṃvatsara · ayana · ṛtu','māsa · pakṣa · tithi (ends at …)','vāra · nakṣatra (ends at …)','yoga · karaṇa','sunrise · sunset','rāhukāla · yamagaṇḍa · gulika','festivals · vratas']))),['<b>The heading.</b> A pañcāṅga page names the year (saṃvatsara), half-year (ayana), season (ṛtu), month (māsa) and fortnight (pakṣa).','<b>The five limbs, with times.</b> Then the tithi, nakṣatra, yoga and karaṇa of the day, each with the clock time at which it ends, since they change in the middle of the day.','<b>Times of the day.</b> Sunrise and sunset for the place, and daily periods many avoid for beginnings: <b>rāhukāla</b> (about an hour and a half, different each weekday), <b>yamagaṇḍa</b> and <b>gulika</b>; and good periods such as <b>abhijit muhūrta</b> around midday.','<b>Place matters.</b> Sunrise, and so the day’s tithi, depends on where you are: a pañcāṅga is calculated for a place. Apps do this automatically; printed almanacs are made for a region.'],[('z','Rāhukāla?'),('b','A daily period of about an hour and a half that many avoid for new beginnings, Zappy. Every pañcāṅga lists it.')],'A day <b>in five limbs and a few hours</b>.'),
 cards('cal1','FESTIVAL MAP · CAITRA–ŚRĀVAṆA','Spring and the rains',fig_row('Spring and monsoon icons',[(lotus(),1.6),(sun(16),1.2),('<path d="M-20 0 l-4 12 M0 0 l-4 12 M20 0 l-4 12" stroke="#5a8ab8" stroke-width="2"/>',1.4),(lamp(),1.6)],['Caitra','Vaiśākha','Āṣāḍha','Śrāvaṇa'],gy=150),[('🌸','Caitra','Śukla 1: '+L('/festivals/ugadi/','Ugādi')+'. Śukla 9: '+L('/festivals/rama-navami/','Rāma Navamī')+'. Pūrṇimā: Hanumān Jayantī (north).'),('☀️','Vaiśākha','Śukla 3: '+L('/festivals/akshaya-tritiya/','Akṣaya Tṛtīyā')+'. Śukla 5: Śaṅkara Jayantī. Śukla 14: Narasiṃha Jayantī. Pūrṇimā: Buddha Pūrṇimā.'),('🌧️','Āṣāḍha','Śukla 11: Śayanī Ekādaśī, start of Cāturmāsya. Pūrṇimā: '+L('/festivals/guru-purnima/','Guru Pūrṇimā')+'.'),('🐍','Śrāvaṇa','Śukla 5: '+L('/festivals/naga-panchami/','Nāga Pañcamī')+'. Friday before pūrṇimā: '+L('/festivals/varamahalakshmi/','Varamahālakṣmī')+'. Pūrṇimā: '+L('/festivals/shravana-purnima/','Upākarma, Rakṣā Bandhan')+'. Kṛṣṇa 8: '+L('/festivals/krishna-janmashtami/','Janmāṣṭamī')+'.')],[('z','Will these ever change?'),('b','Never, Zappy. The tithi stays fixed; only the Western date moves each year.')],'Month names: <b>Karnataka’s amānta</b>.'),
 cards('cal2','FESTIVAL MAP · BHĀDRAPADA–KĀRTIKA','The festival season',fig_row('Gaṇeśa, the Devī, a lamp and a tulasī',[(ganesha(),.9),(devi(),.8),(lamp(),1.6),(tulasi(),1)],['Bhādrapada','Āśvayuja','Dīpāvali','Kārtika'],gy=150),[('🐘','Bhādrapada','Śukla 3: '+L('/ganesha/festivals/gauri-ganesha-habba/','Gaurī')+'. Śukla 4: '+L('/ganesha/festivals/ganesha-chaturthi/','Gaṇeśa Caturthī')+'. Śukla 14: Ananta Caturdaśī. Kṛṣṇa fortnight: '+L('/festivals/pitru-paksha/','Pitṛ Pakṣa')+', ending with Mahālaya Amāvāsyā.'),('🦁','Āśvayuja','Śukla 1–9: '+L('/festivals/navaratri/','Navarātri')+'. Śukla 10: Vijayadaśamī, the '+L('/festivals/navaratri/mysuru-dasara/','Mysuru Dasarā')+'.'),('🪔','Dīpāvali','Kṛṣṇa 13 to Kārtika Śukla 2: '+L('/festivals/deepavali/','Dīpāvali')+', with the Lakṣmī Pūjā on the amāvāsyā that ends Āśvayuja (Kārtika amāvāsyā in the north).'),('🌿','Kārtika','The '+L('/festivals/kartika/','month of lamps')+': Śukla 11–12 Prabodhinī and Tulasī Vivāha; Pūrṇimā: Kārtika Pūrṇimā and Kārttikai Dīpam (with Kṛttikā).')],[('z','Dīpāvali isn’t in Kārtika?'),('b','Its big night is the amāvāsyā ending Āśvayuja in Karnataka’s reckoning, Zappy; the north calls the same night Kārtika amāvāsyā.')],'From Gaṇeśa <b>to the lamps</b>.'),
 cards('cal3','FESTIVAL MAP · MĀRGAŚĪRṢA–PHĀLGUNA','Winter, spring, and every month',fig_row('A gate, a chariot, a liṅga and colours',[(palace(),.6),(sun(16),1.2),(linga(),1.2),(lotus('#e0306a','#c0392b'),1.6)],['Mārgaśīrṣa','Māgha','Śivarātri','Phālguna'],gy=150),[('🚪','Mārgaśīrṣa','Śukla 6: '+L('/subramanya/shashthi/','Subrahmaṇya Ṣaṣṭhī')+'. Śukla 11: '+L('/festivals/vaikuntha-ekadashi/','Vaikuṇṭha Ekādaśī')+' (in solar Dhanus) and Gītā Jayantī. Śukla 13: '+L('/festivals/hanuman-jayanti/','Hanumad vrata')+'. Pūrṇimā: Datta Jayantī. Solar Dhanus: '+L('/festivals/dhanurmasa/','Dhanurmāsa')+'.'),('☀️','Pauṣa and Māgha','Sun into Makara: '+L('/festivals/makara-sankranti/','Saṅkrānti')+'. Māgha Śukla 4: '+L('/ganesha/festivals/ganesha-jayanti/','Gaṇeśa Jayantī')+'. Śukla 5: Vasanta Pañcamī. Śukla 7: '+L('/festivals/ratha-saptami/','Ratha Saptamī')+'.'),('🔱','End of Māgha','Kṛṣṇa 14: '+L('/festivals/maha-shivaratri/','Mahāśivarātri')+' (Phālguna Kṛṣṇa in the north).'),('🎨','Phālguna and every month','Pūrṇimā: '+L('/festivals/holi/','Holi')+'. Every month: '+L('/festivals/ekadashi/','Ekādaśī')+' (both halves), '+L('/ganesha/festivals/sankashti-chaturthi/','Saṅkaṣṭī')+' (Kṛṣṇa 4), '+L('/festivals/pradosha/','Pradoṣa')+' (13th), Māsa Śivarātri (Kṛṣṇa 14).')],[('z','So I can find any festival with this?'),('b','With these three pages and a pañcāṅga, Zappy, yes.')],'The whole year <b>on three pages</b>.'),
 end(i,['<b>Five limbs.</b> Tithi, vāra, nakṣatra, yoga, karaṇa.','<b>Tithi.</b> 12° of moon on sun; 30 a month; it decides most festivals.','<b>Two systems.</b> Amānta (Karnataka) and pūrṇimānta (north): same night, different month name.','<b>Sun.</b> Saṅkrāntis fix solar festivals; the adhika māsa keeps the seasons.','<b>Dating.</b> Sunrise, midday, dusk or midnight rules; almanacs may differ by a day.'],'Next: '+L('/festivals/makara-sankranti/','Makara Saṅkrānti')+', the festival that follows the sun.','The pañcāṅga: how the calendar works'),
 sources([('Calendar:','Wikipedia, “Panchangam”, “Hindu calendar”, “Tithi”, “Nakshatra”, “Adhik Maas”; Hindupedia, “Pañcāṅga” (five limbs); Agni Purāṇa ch. 122 (wisdomlib.org) for the traditional computation chapter.'),('Festival rules:','Our festival guides on this site, which cite their own sources for each date rule.')],'regional differences in month names, new-year days and festival rules (summarised); the deities of weekdays (popular practice); the sixty-year cycle’s exact start in different regions; Kali-yuga year count (traditional).','We describe the calendar; for any particular date, consult your family’s almanac.')]
build(i,'FIVE LIMBS · TITHI TO KARAṆA · THE FESTIVAL MAP',COV,'Sun, moon and the almanac','The <b>five limbs</b> one by one, months and seasons, <b>amānta and pūrṇimānta</b>, solar months, the <b>extra month</b>, the eras, how a festival’s day is chosen, how to read a page, and a <b>map of the year’s festivals</b>.','The Hindu calendar explained: the pañcāṅga’s five limbs (tithi, vāra, nakṣatra, yoga, karaṇa), the twelve months and six seasons, amānta and pūrṇimānta, solar months and saṅkrānti, adhika māsa, the eras and sixty named years, how festival dates are chosen, reading a pañcāṅga, and a month-by-month festival map.',pp)
print('pc ok',len(pp)+2)
